def make_image(
    path,
    width,
    height,
    brightness=1.0
):

    if not path.exists():

        return None

    try:

        img = Image.open(
            path
        ).convert("RGB")

        source_ratio = (
            img.width /
            img.height
        )

        target_ratio = (
            width /
            height
        )

        if source_ratio > target_ratio:

            new_height = height

            new_width = int(
                height *
                source_ratio
            )

        else:

            new_width = width

            new_height = int(
                width /
                source_ratio
            )

        img = img.resize(
            (
                new_width,
                new_height
            ),
            Image.Resampling.LANCZOS
        )

        left = (
            img.width -
            width
        ) // 2

        top = (
            img.height -
            height
        ) // 2

        img = img.crop(
            (
                left,
                top,
                left + width,
                top + height
            )
        )

        if brightness != 1.0:

            img = ImageEnhance.Brightness(
                img
            ).enhance(
                brightness
            )

        return ctk.CTkImage(
            light_image=img,
            dark_image=img,
            size=(
                width,
                height
            )
        )

    except Exception as error:

        print(
            "❌ Lỗi ảnh:",
            error
        )

        return None


