conservation_window = None

def show_conservation():
    global conservation_window

    if conservation_window is not None and conservation_window.winfo_exists():
        conservation_window.lift()
        conservation_window.focus_force()
        return

    conservation_window = ctk.CTkToplevel(app)
    conservation_window.title("Bảo tồn sinh vật và hệ sinh thái biển Côn Đảo")
    conservation_window.geometry("1150x780")
    conservation_window.minsize(900, 650)
    conservation_window.configure(fg_color=BG)

    top = ctk.CTkFrame(conservation_window, height=90, corner_radius=0, fg_color=HEADER)
    top.pack(fill="x")
    top.pack_propagate(False)

    ctk.CTkLabel(top, text="🛡️ BẢO TỒN CÔN ĐẢO", font=("Arial", 26, "bold"), text_color=CYAN).pack(anchor="w", padx=30, pady=(16, 0))
    ctk.CTkLabel(top, text="Thực trạng, giá trị và định hướng bảo tồn hệ sinh thái biển", font=("Arial", 11), text_color=MUTED).pack(anchor="w", padx=32, pady=(2, 0))

    content = ctk.CTkScrollableFrame(conservation_window, fg_color=BG, scrollbar_button_color="#145969", scrollbar_button_hover_color="#1D7487")
    content.pack(fill="both", expand=True, padx=20, pady=15)

    def section(icon, title, text, accent=CYAN):
        card = ctk.CTkFrame(content, corner_radius=18, fg_color=PANEL, border_width=1, border_color="#145969")
        card.pack(fill="x", padx=10, pady=8)
        ctk.CTkLabel(card, text=f"{icon}  {title}", font=("Arial", 16, "bold"), text_color=accent).pack(anchor="w", padx=20, pady=(15, 6))
        ctk.CTkLabel(card, text=text, font=("Arial", 11), text_color=WHITE, justify="left", anchor="w", wraplength=1000).pack(fill="x", padx=20, pady=(0, 16))

    section("🌊", "Hệ sinh thái biển Côn Đảo", "Công cuộc bảo tồn hệ sinh thái và tài nguyên biển Côn Đảo được khởi xướng sau khi thành lập Vườn quốc gia Côn Đảo. Công tác theo dõi, giám sát với sự tham gia của chuyên gia khoa học và cán bộ Vườn quốc gia giúp nhận diện các thách thức và định hướng bảo tồn trong tương lai.")

    section("🪸", "Rạn san hô", "Rạn san hô chịu tác động lớn từ bão Linda (11/1997) và sự cố tẩy trắng san hô năm 1998. Đến năm 2005, san hô có phục hồi nhưng độ phủ san hô cứng trung bình chỉ trên 23,9%; đến năm 2019 rạn san hô phục hồi gần như nguyên trạng. Tuy vậy, hiện tượng tẩy trắng tiếp tục xảy ra vào các năm 2010, 2016 và 2019 do nhiệt độ nước biển tầng mặt tăng. Một số khu vực chịu tác động của con người có độ phủ thấp, như khoảng 30% ở Cựa Gà và 15% ở Bãi Cát Lớn.", YELLOW)

    section("🌱", "Thảm cỏ biển và Bò biển", "Thảm cỏ biển có ý nghĩa quan trọng về sinh thái và là nguồn sống của Bò biển. Tài liệu ghi nhận độ phú của thảm cỏ biển có xu hướng suy giảm mạnh, chỉ bằng khoảng 1/10 so với năm 2009-2010; đồng thời đã quan sát thấy dấu hiệu suy thoái chất lượng như phủ trầm tích và rong phụ sinh. Cần đánh giá đúng đặc trưng thảm cỏ biển và tăng cường quản lý chất thải, đặc biệt là chất thải hữu cơ.")

    section("🐟", "Sinh vật rạn san hô", "Mật độ cá Bướm tăng cùng với sự cải thiện độ phủ san hô, trong khi một số loài có giá trị thực phẩm suy giảm hoặc duy trì ở mật độ thấp. Mật độ nhóm cá Hồng được ghi nhận giảm từ 80 xuống 20 con/100 m²; mật độ Trai Tai tượng giảm 4 lần trong giai đoạn 2005-2019. Phục hồi Trai Tai tượng, Ốc đụn, Bào ngư và phục hồi san hô là những giải pháp có ý nghĩa cả về sinh thái và kinh tế.")

    section("🐢", "Bảo tồn Rùa biển", "Trong giai đoạn 2009-2019, trung bình gần 1.500 tổ Rùa xanh được di dời chăm sóc mỗi năm, tương ứng hơn 137.000 trứng và gần 110.000 rùa con nở. Các chỉ số này tăng xấp xỉ gấp đôi so với giai đoạn 1998-2008. Tỷ lệ rùa nở và di chuyển ra biển sau đó khá ổn định, khoảng 75-85% tổng số trứng. Đây là một kết quả nổi bật của công tác bảo tồn Rùa biển tại Côn Đảo.", GREEN)

    section("🎯", "Định hướng bảo tồn đến năm 2030", "• Bảo tồn hiệu quả đa dạng hệ sinh thái biển, nhất là rạn san hô và thảm cỏ biển.\n• Bảo vệ và phục hồi các loài quý hiếm, bị đe dọa, chú trọng Bò biển, Rùa biển, Trai Tai tượng, Ốc đụn cái, Trai ngọc môi vàng và Cầu gai đá.\n• Phục hồi san hô cứng để cải thiện độ phủ và mở rộng sinh cư cho Rùa biển.\n• Hỗ trợ hệ sinh thái thích ứng với biến đổi khí hậu và giảm tác động tiêu cực của hoạt động kinh tế - xã hội.\n• Nâng cao năng lực nghiên cứu, giám sát tài nguyên - môi trường biển; huy động cộng đồng và doanh nghiệp tham gia bảo tồn.")

    source = ctk.CTkFrame(content, corner_radius=15, fg_color="#061F2A")
