def stat_card(
    icon,
    title,
    value,
    detail,
    color
):

    card = ctk.CTkFrame(
        stats,
        height=110,
        corner_radius=17,
        fg_color=PANEL
    )

    card.pack(
        side="left",
        fill="both",
        expand=True,
        padx=5
    )

    card.pack_propagate(
        False
    )


    ctk.CTkLabel(
        card,
        text=icon,
        font=(
            "Arial",
            23
        )
    ).place(
        x=18,
        y=12
    )


    ctk.CTkLabel(
        card,
        text=title,
        font=(
            "Arial",
            11,
            "bold"
        ),
        text_color=WHITE
    ).place(
        x=55,
        y=18
    )


    ctk.CTkLabel(
        card,
        text=value,
        font=(
            "Arial",
            21,
            "bold"
        ),
        text_color=color
    ).place(
        x=18,
        y=48
    )


    ctk.CTkLabel(
        card,
        text=detail,
        font=(
            "Arial",
            9
        ),
        text_color=MUTED
    ).place(
        x=18,
        y=84
    )


