def image_card(
    path,
    title,
    description
):

    card = ctk.CTkFrame(
        cards,
        height=145,
        corner_radius=18,
        fg_color=PANEL2
    )

    card.pack(
        side="left",
        fill="both",
        expand=True,
        padx=5
    )

    card.pack_propagate(
        False
    )


    photo = make_image(
        path,
        310,
        145,
        0.62
    )


    if photo:

        label = ctk.CTkLabel(
            card,
            image=photo,
            text=""
        )

        label.place(
            x=0,
            y=0,
            relwidth=1,
            relheight=1
        )

        card.photo = photo

    else:

        ctk.CTkLabel(
            card,
            text="Không tìm thấy ảnh",
            text_color=RED
        ).place(
            relx=0.5,
            rely=0.5,
            anchor="center"
        )


    shade = ctk.CTkFrame(
        card,
        width=150,
        height=145,
        corner_radius=0,
        fg_color="#031923"
    )

    shade.place(
        relx=0.52,
        rely=0
    )

    shade.pack_propagate(
        False
    )


    ctk.CTkLabel(
        shade,
        text=title,
        font=(
            "Arial",
            13,
            "bold"
        ),
        text_color=WHITE,
        wraplength=125,
        justify="left"
    ).pack(
        anchor="w",
        padx=12,
        pady=(25, 5)
    )


    ctk.CTkLabel(
        shade,
        text=description,
        font=(
            "Arial",
            9
        ),
        text_color=MUTED,
        wraplength=125,
        justify="left"
    ).pack(
        anchor="w",
        padx=12
    )


