# =========================================================
# 10. GEMINI ANALYSIS
# =========================================================

def ask_gemini(
    image_path,
    detections
):

    try:
        import time

        gemini_start = time.perf_counter()

        # Nếu YOLO không phát hiện gì thì không cần gửi ảnh lên Gemini.
        if not detections:
            return (
                "❌ Không phát hiện sinh vật.\n\n"
                "Vui lòng thử một ảnh rõ hơn."
            )

        # =====================================================
        # GIẢM KÍCH THƯỚC ẢNH TRƯỚC KHI GỬI GEMINI
        # =====================================================

        img = Image.open(image_path).convert("RGB")

        # Gemini không cần ảnh 2K/4K cho phần phân tích thông tin.
        img.thumbnail(
            (768, 768),
            Image.Resampling.LANCZOS
        )

        # Lưu thành JPEG để giảm dung lượng request.
        temp_path = BASE_DIR / "gemini_temp.jpg"

        img.save(
            temp_path,
            "JPEG",
            quality=80,
            optimize=True
        )

        with open(
            temp_path,
            "rb"
        ) as file:
            image_bytes = file.read()

        print(
            f"📷 Ảnh gửi Gemini: "
            f"{len(image_bytes) / 1024:.1f} KB"
        )

        # =====================================================
        # KẾT QUẢ YOLO
        # =====================================================

        yolo_text = "\n".join(
            [
                (
                    f"- {name}: "
                    f"{confidence * 100:.1f}%"
                )
                for name, confidence in detections
            ]
        )

        # =====================================================
        # PROMPT NGẮN GỌN
        # =====================================================

        prompt = f"""
Bạn là trợ lý AI hỗ trợ bảo tồn sinh vật tại Côn Đảo.

YOLO đã nhận diện:
{yolo_text}

Hãy cung cấp thông tin ngắn gọn bằng tiếng Việt.

1. Tên sinh vật
2. Đặc điểm chính
3. Môi trường sống
4. Vai trò sinh thái
5. Khuyến nghị bảo tồn

Mỗi mục chỉ 1-2 câu.
Không cần nhận diện lại loài nếu YOLO đã cung cấp tên.
Không khẳng định tuyệt đối nếu ảnh không đủ rõ.
"""

        print("✨ Gemini đang gửi yêu cầu...")

        # =====================================================
        # GỌI GEMINI
        # =====================================================

        request_start = time.perf_counter()

        response = (
            gemini_client
            .models
            .generate_content(
                model=GEMINI_MODEL,
                contents=[
                    prompt,
                    genai.types.Part.from_bytes(
                        data=image_bytes,
                        mime_type="image/jpeg"
                    )
                ]
            )
        )

        request_time = time.perf_counter() - request_start
        total_time = time.perf_counter() - gemini_start

        print(
            f"⚡ Gemini API: {request_time:.2f} giây"
        )

        print(
            f"⏱️ Tổng thời gian Gemini: "
            f"{total_time:.2f} giây"
        )

        # Xóa ảnh tạm sau khi request hoàn tất.
        try:
            temp_path.unlink(missing_ok=True)
        except Exception:
            pass

        return response.text

    except Exception as error:

        print(
            "❌ GEMINI ERROR:",
            error
        )

        return (
            "❌ Gemini gặp lỗi.\n\n"
            f"{error}"
        )


# =========================================================
# 11. CẬP NHẬT YOLO
# =========================================================

def update_yolo_result(
    detections
):

    global is_analyzing

    if detections:

        best_name = detections[0][0]

        best_conf = detections[0][1]

        yolo_result.configure(
            text=(
                f"🐠 {best_name}\n"
                f"Phát hiện "
                f"{len(detections)} đối tượng"
            ),
            text_color=GREEN
        )

        confidence_value.configure(
            text=(
                f"{best_conf * 100:.1f}%"
            )
        )

        confidence_bar.set(
            best_conf
        )

    else:

        yolo_result.configure(
            text="❌ Không phát hiện sinh vật",
            text_color=RED
        )

        confidence_value.configure(
            text="0.0%"
        )

        confidence_bar.set(
            0
        )


# =========================================================
# 12. CẬP NHẬT GEMINI
# =========================================================

def update_gemini_result(
    answer
):

    global is_analyzing

    gemini_box.configure(
        state="normal"
    )

    gemini_box.delete(
        "1.0",
        "end"
    )

    gemini_box.insert(
        "1.0",
        answer
    )

    gemini_box.configure(
        state="disabled"
    )

    is_analyzing = False

    choose_button.configure(
        state="normal",
        text="📂  CHỌN ẢNH"
    )


# =========================================================
# 13. LUỒNG PHÂN TÍCH NỀN
# =========================================================

def analyze_image_background(
    image_path
):

    global is_analyzing

    detections = []


    # =====================================================
    # YOLO
    # =====================================================

    try:

        print()
        print("🤖 YOLO đang nhận diện...")


        results = model.predict(
            source=image_path,

            # Hạ xuống để model dễ phát hiện hơn
            conf=0.15,

            verbose=False
        )


        result = results[0]


        if result.boxes is not None:

            for box in result.boxes:

                class_id = int(
                    box.cls[0]
                )

                confidence = float(
                    box.conf[0]
                )

                class_name = model.names[
                    class_id
                ]

                detections.append(
                    (
                        class_name,
                        confidence
                    )
                )


        detections.sort(
            key=lambda x: x[1],
            reverse=True
        )


        print("✅ YOLO hoàn tất")


        for name, confidence in detections:

            print(
                f"   • {name}: "
                f"{confidence * 100:.2f}%"
            )


    except Exception as error:

        print(
            "❌ YOLO ERROR:",
            error
        )

        detections = []


    # =====================================================
    # UPDATE YOLO TRÊN MAIN THREAD
    # =====================================================

    app.after(
        0,
        lambda d=detections:
        update_yolo_result(d)
    )


    # =====================================================
    # GEMINI
    # =====================================================

    print(
        "✨ Gemini đang phân tích..."
    )


    gemini_answer = ask_gemini(
        image_path,
        detections
    )


    print(
        "✅ Gemini hoàn tất"
    )


    # =====================================================
    # UPDATE GEMINI TRÊN MAIN THREAD
    # =====================================================

    app.after(
        0,
        lambda a=gemini_answer:
        update_gemini_result(a)
    )


# =========================================================
# 14. PHÂN TÍCH ẢNH
# =========================================================

def analyze_image(
    image_path
):

    global is_analyzing

    if is_analyzing:

        messagebox.showinfo(
            "AI đang xử lý",
            "Hệ thống đang phân tích ảnh.\n"
            "Vui lòng chờ kết quả hiện tại."
        )

        return


    is_analyzing = True


    # -----------------------------------------------------
    # TRẠNG THÁI
    # -----------------------------------------------------

    yolo_result.configure(
        text="⏳ YOLO đang nhận diện...",
        text_color=CYAN
    )


    confidence_value.configure(
        text="..."
    )


    confidence_bar.set(
        0
    )


    gemini_box.configure(
        state="normal"
    )

    gemini_box.delete(
        "1.0",
        "end"
    )

    gemini_box.insert(
        "1.0",
        "🤖 AI đang phân tích...\n\n"
        "YOLO đang nhận diện sinh vật.\n"
        "Sau đó Gemini sẽ phân tích hình ảnh.\n\n"
        "Bạn vẫn có thể sử dụng giao diện."
    )

    gemini_box.configure(
        state="disabled"
    )


    choose_button.configure(
        state="disabled",
        text="⏳ ĐANG PHÂN TÍCH..."
    )


    # -----------------------------------------------------
    # THREAD
    # -----------------------------------------------------

    thread = threading.Thread(
        target=analyze_image_background,
        args=(image_path,),
        daemon=True
    )

    thread.start()


# =========================================================
# 15. CHỌN ẢNH
# =========================================================

def choose_image():

    global current_photo


    file_path = filedialog.askopenfilename(
        title="Chọn ảnh sinh vật biển",

        filetypes=[
            (
                "Image files",
                "*.jpg *.jpeg *.png *.webp *.bmp"
            )
        ]
    )


    if not file_path:

        return


    try:

        img = Image.open(
            file_path
        ).convert("RGB")


        display_img = img.copy()


        display_img.thumbnail(
            (
                550,
                340
            ),
            Image.Resampling.LANCZOS
        )


        current_photo = ctk.CTkImage(
            light_image=display_img,
            dark_image=display_img,
            size=display_img.size
        )


        preview_label.configure(
            image=current_photo,
            text=""
        )


        analyze_image(
            file_path
        )


    except Exception as error:

        messagebox.showerror(
            "Lỗi",
            f"Không thể mở ảnh:\n\n{error}"
        )


